import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor min_reduce_dim_forward(torch::Tensor x, int64_t dim);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cfloat>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void min_reduce_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    int64_t outer, int64_t reduce_size, int64_t inner)
{
    // Represent input as a 3D tensor (outer, reduce_size, inner) contiguous
    auto mX = make_tensor(
        make_gmem_ptr(X),
        make_shape(outer, reduce_size, inner),
        make_stride(reduce_size * inner, inner, Int<1>{})
    );

    // Output as a 2D tensor (outer, inner)
    auto mY = make_tensor(
        make_gmem_ptr(Y),
        make_shape(outer, inner),
        make_stride(inner, Int<1>{})
    );

    int64_t o = blockIdx.x;
    int64_t i = (int64_t)blockIdx.y * blockDim.x + threadIdx.x;

    if (o >= outer || i >= inner) return;

    T acc = __ldg(&mX(o, 0, i));
    #pragma unroll 8
    for (int64_t k = 1; k < reduce_size; ++k) {
        T v = __ldg(&mX(o, k, i));
        acc = v < acc ? v : acc;
    }

    mY(o, i) = acc;
}

torch::Tensor min_reduce_dim_forward(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

    auto x_c = x.contiguous();
    int64_t ndim = x_c.dim();
    if (dim < 0) dim += ndim;
    TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");

    int64_t outer = 1;
    for (int64_t d = 0; d < dim; ++d) outer *= x_c.size(d);
    int64_t reduce_size = x_c.size(dim);
    int64_t inner = 1;
    for (int64_t d = dim + 1; d < ndim; ++d) inner *= x_c.size(d);

    std::vector<int64_t> out_shape;
    for (int64_t d = 0; d < ndim; ++d) {
        if (d != dim) out_shape.push_back(x_c.size(d));
    }

    auto y = torch::empty(out_shape, x_c.options());

    const float* x_ptr = x_c.data_ptr<float>();
    float* y_ptr = y.data_ptr<float>();

    constexpr int Threads = 256;
    dim3 block(Threads);
    dim3 grid(
        (unsigned)outer,
        (unsigned)((inner + Threads - 1) / Threads)
    );

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    min_reduce_kernel<float><<<grid, block, 0, stream>>>(
        x_ptr, y_ptr, outer, reduce_size, inner
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "min_reduce_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
"""

min_reduce_ext = load_inline(
    name="cute_min_reduce_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["min_reduce_dim_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs min reduction over a specific dimension,
    implemented with a custom CUDA kernel using CuTe tensor abstractions.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self._ext = min_reduce_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.min_reduce_dim_forward(x.contiguous(), int(self.dim))

